/* Read-only registered LOT picker for raw, intermediate and finished modes. Existing trace controls own all trace queries. */
(()=>{'use strict';
const root=document.querySelector('#lotTrace'),input=root?.querySelector('#lotQueryInput');if(!input)return;
let popup=null,rows=[],pending=null,version=0;
const mode=()=>root.querySelector('#lotIntermediateMode')?.classList.contains('active')?'intermediate':root.querySelector('#lotFinishedMode')?.classList.contains('active')?'finished':'raw';
const title=()=>({raw:'원자재 LOT',intermediate:'중간재 배치번호',finished:'완제품 LOT'}[mode()]);
const parse=v=>{if(typeof v==='string'){try{return JSON.parse(v);}catch(_){return {};}}return v||{};};
const unpack=v=>{v=parse(v);return Array.isArray(v)?v:Array.isArray(v.rows)?v.rows:Array.isArray(v.data)?v.data:[];};
const clean=v=>{const s=String(v??'').trim();return /^(?:-|null|undefined)$/i.test(s)?'':s;};
function close(){version++;pending?.abort();pending=null;popup?.remove();popup=null;input.setAttribute('aria-expanded','false');}
function position(){if(!popup)return;const r=input.getBoundingClientRect(),height=Math.min(popup.scrollHeight,300);popup.style.width=Math.min(Math.max(r.width,330),innerWidth-16)+'px';popup.style.left=Math.max(8,Math.min(r.left,innerWidth-popup.getBoundingClientRect().width-8))+'px';popup.style.top=(r.bottom+height+5<innerHeight?r.bottom+4:Math.max(8,r.top-height-4))+'px';}
function message(text){const el=document.createElement('div');el.className='qlp-message';el.textContent=text;return el;}
function choose(row){input.value=row.lot;input.dispatchEvent(new Event('input',{bubbles:true}));close();root.querySelector('#lotSearchBtn').click();}
function draw(warning=''){if(!popup)return;const q=input.value.trim().toLocaleUpperCase(),matches=rows.filter(r=>[r.lot,...r.names].join(' ').toLocaleUpperCase().includes(q));popup.replaceChildren();if(warning)popup.append(message(warning));const list=document.createElement('div');list.className='qlp-options';list.setAttribute('role','listbox');list.id='qmes-raw-lot-options';list.setAttribute('aria-label','등록된 '+title());for(const row of matches){const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(input.value===row.lot));const lot=document.createElement('strong'),name=document.createElement('span');lot.textContent=row.lot;name.textContent=row.names.join(' / ')||title();button.append(lot,name);button.addEventListener('click',()=>choose(row));list.append(button);}if(!matches.length)list.append(message(rows.length?'일치하는 '+title()+'가 없습니다.':warning?'LOT 목록을 불러오지 못했습니다.':'등록된 '+title()+'가 없습니다.'));popup.append(list);position();}
async function open(){close();const current=version,requested=mode();popup=document.createElement('div');popup.className='qmes-raw-lot-picker';popup.append(message(title()+' 목록을 불러오고 있습니다.'));document.body.append(popup);input.setAttribute('aria-expanded','true');position();pending=new AbortController();const controller=pending,timer=setTimeout(()=>controller.abort(),12000);
async function read(url,label){try{const res=await fetch(url,{credentials:'same-origin',cache:'no-store',signal:controller.signal}),json=await res.json();if(!res.ok||json.success===false||!Array.isArray(json.data))throw Error('조회 실패');return {label,rows:json.data};}catch(e){return {label,rows:[],error:true};}}
try{const paths=requested==='raw'?[['/api/iqc','수입검사'],['/api/inventory/stock','원자재 재고']]:requested==='intermediate'?[['/api/qmes/work-orders','작업지시']]:[['/api/qmes/work-orders','작업지시'],['/api/trace?keyword=','작업실적'],['/api/pqc','공정검사'],['/api/oqc','출하검사'],['/api/qmes-sync/pqc','공정검사 공용기록'],['/api/qmes-sync/oqc','출하검사 공용기록'],['/api/qmes-sync/inventory','출하실적'],['/api/inventory/stock','완제품 재고']];const sources=await Promise.all(paths.map(([url,label])=>read(url,label)));if(current!==version||!popup||mode()!==requested)return;const map=new Map();function add(lot,name){lot=clean(lot);name=clean(name);if(!lot)return;const key=lot.toLocaleUpperCase();let row=map.get(key);if(!row){row={lot,names:[]};map.set(key,row);}if(name&&!row.names.includes(name))row.names.push(name);}
if(requested==='raw'){sources[0].rows.filter(r=>!r.deleted).forEach(r=>add(r.lot,r.item));sources[1].rows.filter(r=>r.category==='RM').forEach(r=>add(r.lot_no,r.item_name));}else{const work=sources[0].rows.filter(r=>!r.deleted);work.filter(r=>requested==='intermediate'?r.productionType==='중간배치':r.productionType!=='중간배치').forEach(r=>add(r.fields?.['생산 LOT NO'],r.fields?.['제품명']||r.intermediateBatch?.kind));if(requested==='finished'){const mids=new Set(work.filter(r=>r.productionType==='중간배치').map(r=>clean(r.fields?.['생산 LOT NO']).toUpperCase()));const finished=(lot,name)=>{if(!mids.has(clean(lot).toUpperCase()))add(lot,name);};sources[1].rows.forEach(r=>finished(r.finishedLot,''));for(const source of sources.slice(2,4))source.rows.filter(r=>!r.deleted).forEach(r=>finished(r.lot,r.product||r.item));for(const source of sources.slice(4,6))source.rows.forEach(record=>{const payload=parse(record.payload);if(!payload.deleted)unpack(payload).filter(r=>!r.deleted).forEach(r=>finished(r.lot,r.product||r.item));});sources[6].rows.filter(r=>r.record_key==='erp:shipping').flatMap(r=>unpack(r.payload)).filter(r=>!r.deleted).forEach(r=>finished(r.lot||r.finishedLot||r.productionLot,r.product||r.item));sources[7].rows.filter(r=>r.category==='FG').forEach(r=>finished(r.lot_no,r.item_name));}}
rows=[...map.values()].sort((a,b)=>a.lot.localeCompare(b.lot,'ko',{numeric:true}));const failed=sources.filter(s=>s.error).map(s=>s.label);popup.dataset.warning=failed.length?failed.join('·')+' 조회 실패 · 다시 클릭하여 재시도하세요.':'';draw(popup.dataset.warning);
}finally{clearTimeout(timer);if(pending===controller)pending=null;}}
input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls','qmes-raw-lot-options');input.setAttribute('aria-expanded','false');input.setAttribute('autocomplete','off');
input.addEventListener('click',()=>{if(!popup||popup.dataset.warning)open();});input.addEventListener('focus',()=>{if(!popup)open();});input.addEventListener('input',()=>{if(popup&&!pending)draw(popup.dataset.warning||'');else if(!popup)open();});
root.querySelector('.lot-mode-native')?.addEventListener('change',()=>{close();open();});
window.addEventListener('keydown',event=>{if(!popup)return;if(event.key==='Escape'){event.preventDefault();close();return;}if(!['ArrowDown','ArrowUp'].includes(event.key))return;const buttons=[...popup.querySelectorAll('[role=option]')];if(!buttons.length)return;if(event.target!==input&&!popup.contains(event.target))return;event.preventDefault();const index=buttons.indexOf(document.activeElement),next=event.key==='ArrowDown'?(index+1)%buttons.length:(index<=0?buttons.length-1:index-1);buttons[next].focus();},true);
document.addEventListener('pointerdown',event=>{if(popup&&event.target!==input&&!popup.contains(event.target))close();},true);window.addEventListener('resize',position);window.addEventListener('scroll',event=>{if(popup&&!popup.contains(event.target))position();},true);
const style=document.createElement('style');style.textContent=`.qmes-raw-lot-picker{position:fixed;z-index:2147483000;box-sizing:border-box;max-height:300px;overflow:auto;background:#fff;border:1px solid #b8c9da;border-radius:5px;box-shadow:0 5px 18px #18335324;color:#243e5d;font:12px Arial,"Malgun Gothic",sans-serif}.qmes-raw-lot-picker .qlp-options{display:flex;flex-direction:column}.qmes-raw-lot-picker [role=option]{display:flex;align-items:flex-start;flex-direction:column;gap:4px;flex:0 0 auto;width:100%;min-height:46px;padding:9px 12px;text-align:left;border:0;border-bottom:1px solid #edf1f6;border-radius:0;background:#fff;color:#243e5d;font:inherit;cursor:pointer}.qmes-raw-lot-picker [role=option]:hover,.qmes-raw-lot-picker [role=option]:focus-visible{background:#edf5ff;outline:2px solid #7bb0e6;outline-offset:-2px}.qmes-raw-lot-picker strong{font-weight:600}.qmes-raw-lot-picker span{color:#66788b;font-size:11px}.qmes-raw-lot-picker .qlp-message{padding:13px 12px;color:#66788b;font-size:12px}`;document.head.append(style);
})();
